<?php

/**
 * One gateway per carrier, its options from the environment (.env): a
 * gateway is configured only when every key under "needs" is set. Factory
 * names are the carriers' own; sandboxes are on unless <CARRIER>_SANDBOX=0.
 *
 * @return array<string, array{factory: string, needs: list<string>, options: array<string, mixed>}>
 */
$env = static fn (string $key, mixed $default = null): mixed => (false !== ($v = getenv($key)) && '' !== $v) ? $v : $default;
$sandbox = static fn (string $prefix): bool => '0' !== $env($prefix.'_SANDBOX', '1');
$rates = static fn (string $service, string $label, int $amount, string $currency = 'EUR'): array => [['service' => $service, 'label' => $label, 'currency' => $currency, 'bands' => [30000 => $amount]]];

return [
    'offline' => ['factory' => 'offline', 'needs' => [], 'options' => ['rates' => [['service' => 'pickup', 'label' => 'Click & collect', 'to_pickup_point' => true, 'bands' => [30000 => 0]]]]],
    'mondial_relay' => ['factory' => 'mondial_relay', 'needs' => [], 'options' => array_filter(['enseigne' => $env('MONDIAL_RELAY_ENSEIGNE'), 'private_key' => $env('MONDIAL_RELAY_PRIVATE_KEY'), 'sandbox' => null === $env('MONDIAL_RELAY_ENSEIGNE'), 'rates' => $rates('24R', 'Point relais', 490)])],
    'colissimo' => ['factory' => 'colissimo', 'needs' => [], 'options' => ['rates' => $rates('DOM', 'Colissimo domicile', 690)]],
    'chronopost' => ['factory' => 'chronopost', 'needs' => ['CHRONOPOST_ACCOUNT', 'CHRONOPOST_PASSWORD'], 'options' => ['account_number' => $env('CHRONOPOST_ACCOUNT'), 'password' => $env('CHRONOPOST_PASSWORD'), 'sub_account' => $env('CHRONOPOST_SUB_ACCOUNT')]],
    'ups' => ['factory' => 'ups', 'needs' => ['UPS_CLIENT_ID', 'UPS_CLIENT_SECRET', 'UPS_ACCOUNT'], 'options' => ['client_id' => $env('UPS_CLIENT_ID'), 'client_secret' => $env('UPS_CLIENT_SECRET'), 'account_number' => $env('UPS_ACCOUNT'), 'sandbox' => $sandbox('UPS')]],
    'fedex' => ['factory' => 'fedex', 'needs' => ['FEDEX_CLIENT_ID', 'FEDEX_CLIENT_SECRET', 'FEDEX_ACCOUNT'], 'options' => ['client_id' => $env('FEDEX_CLIENT_ID'), 'client_secret' => $env('FEDEX_CLIENT_SECRET'), 'account_number' => $env('FEDEX_ACCOUNT'), 'sandbox' => $sandbox('FEDEX')]],
    'dhl' => ['factory' => 'dhl', 'needs' => ['DHL_API_KEY', 'DHL_API_SECRET', 'DHL_ACCOUNT'], 'options' => ['api_key' => $env('DHL_API_KEY'), 'api_secret' => $env('DHL_API_SECRET'), 'account_number' => $env('DHL_ACCOUNT'), 'location_api_key' => $env('DHL_LOCATION_KEY'), 'sandbox' => $sandbox('DHL')]],
